-- 宠物指令与 PvP 状态：这些行的 text_loc4 原本是德语，中文客户端会看到德文。
UPDATE `ai_playerbot_texts` SET `text_loc4` = CASE `id`
    WHEN 1717 THEN '用法：pet <aggressive|defensive|passive|stance|attack|follow|stay>',
    WHEN 1718 THEN '你没有任何宠物或守护宠物。',
    WHEN 1719 THEN '当前姿态：%type "%name"：%stance。',
    WHEN 1720 THEN '主人没有选中有效的目标。',
    WHEN 1721 THEN '目标已经死亡。',
    WHEN 1722 THEN '该目标不是宠物可以攻击的有效目标。',
    WHEN 1723 THEN '在禁止 PvP 的区域，我无法命令宠物攻击玩家。',
    WHEN 1724 THEN '已命令宠物攻击你的目标。',
    WHEN 1725 THEN '宠物没有发起攻击。（已在攻击，或无法攻击该目标）',
    WHEN 1726 THEN '已命令宠物跟随。',
    WHEN 1727 THEN '已命令宠物停留在原地。',
    WHEN 1728 THEN '未知的宠物指令：%param。用法：pet <aggressive|defensive|passive|stance|attack|follow|stay>',
    WHEN 1729 THEN '宠物姿态已设为 %stance。',
    WHEN 1736 THEN '我没有鱼竿',
    WHEN 1737 THEN '[PVP] 竞技场点数：%arena_points | 荣誉点数：%honor_points',
    WHEN 1738 THEN '[PVP] %bracket：<%team_name>（等级 %team_rating）',
    WHEN 1739 THEN '[PVP] 我没有竞技场队伍。'
    ELSE `text_loc4` END
WHERE `id` IN (1717, 1718, 1719, 1720, 1721, 1722, 1723, 1724, 1725, 1726, 1727, 1728, 1729, 1736, 1737, 1738, 1739);
